using System.Collections.ObjectModel;
using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using CommerceErp.Core;
namespace CommerceErp.Desktop;
public sealed class InventoryLineDraft
{
    public string Code{get;set;}="";public decimal Value{get;set;}public decimal QuarantineCount{get;set;}public decimal BookOnHand{get;set;}public decimal BookQuarantine{get;set;}public decimal Reserved{get;set;}public decimal Frozen{get;set;}public decimal? StoredHandDelta{get;set;}public decimal? StoredQuarantineDelta{get;set;}public InventoryDocumentBalance? Captured{get;set;}
}
public sealed record InventoryKindChoice(InventoryDocumentKind Kind,string Name);
public partial class InventoryDocumentWindow:Window
{
    private readonly LocalApiClient _api;private InventoryDocument? _document;private bool _busy;private int _page=1;public ObservableCollection<InventoryLineDraft> Rows{get;}=[];
    public InventoryDocumentWindow(LocalApiClient api){InitializeComponent();_api=api;LinesGrid.ItemsSource=Rows;KindBox.ItemsSource=new[]{new InventoryKindChoice(InventoryDocumentKind.Adjustment,"库存调整"),new(InventoryDocumentKind.Count,"盘点"),new(InventoryDocumentKind.QuarantineRelease,"隔离转良品"),new(InventoryDocumentKind.QuarantineScrap,"隔离报损"),new(InventoryDocumentKind.QuarantineReturn,"隔离退供出库"),new(InventoryDocumentKind.Reversal,"冲销（原单生成）")};StateBox.ItemsSource=new[]{"","Draft","Approved","Voided","Reversed"};StateBox.SelectedIndex=0;NewDocument();}
    private async Task Run(Func<Task> action){if(_busy)return;_busy=true;IsEnabled=false;try{await action();}catch(Exception e){StatusText.Text=e.Message+(_api.PendingCount>0?" 未确认请求保留，请使用原账号在订单中心重试。":"");}finally{_busy=false;IsEnabled=true;Permissions();}}
    private void Permissions(){LinesGrid.IsReadOnly=!_api.Allows("stockdocs.write")||(_document is not null&&(_document.State!="Draft"||_document.Kind==InventoryDocumentKind.Reversal));CreateButton.IsEnabled=_document is null&&_api.Allows("stockdocs.write");EditButton.IsEnabled=_document?.State=="Draft"&&_document.Kind!=InventoryDocumentKind.Reversal&&_api.Allows("stockdocs.write");VoidButton.IsEnabled=_document?.State=="Draft"&&_api.Allows("stockdocs.write");ApproveButton.IsEnabled=_document?.State=="Draft"&&_api.Allows("stockdocs.approve")&&_document.CreatedBy!=_api.CurrentAccount?.Id;ReverseButton.IsEnabled=_document?.State=="Approved"&&_document.Kind!=InventoryDocumentKind.Reversal&&_api.Allows("stockdocs.write");}
    public void NewDocument(){_document=null;KindBox.IsEnabled=true;NumberBox.IsReadOnly=false;KindBox.SelectedIndex=0;NumberBox.Text="INV-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N")[..4];Rows.Clear();EvidenceBox.Clear();ReasonBox.Clear();MovementsGrid.ItemsSource=null;HistoryGrid.ItemsSource=null;Permissions();}
    public async Task RefreshAsync(){var p=await _api.GetAsync<MasterPage<InventoryDocument>>($"/api/inventory-documents?page={_page}&size=30&search={Uri.EscapeDataString(SearchBox.Text)}&state={StateBox.SelectedItem}");DocumentsGrid.ItemsSource=p.Items;PageText.Text=$"第{p.Page}页 / 共{p.Total}单";Permissions();}
    private void Commit(){if(!LinesGrid.CommitEdit(DataGridEditingUnit.Cell,true)||!LinesGrid.CommitEdit(DataGridEditingUnit.Row,true))throw new BusinessRuleException("请检查明细输入。");}
    public async Task CaptureAsync(){Commit();if(Rows.Count is <1 or >200)throw new BusinessRuleException("请输入1–200行。");foreach(var row in Rows){var b=await _api.GetAsync<InventoryDocumentBalance>("/api/inventory-documents/by-code/"+Uri.EscapeDataString(row.Code.Trim()));row.Code=b.Code;row.Captured=b;row.BookOnHand=b.OnHand;row.BookQuarantine=b.Quarantined;row.Reserved=b.Reserved;row.Frozen=b.Frozen;}LinesGrid.Items.Refresh();StatusText.Text="已捕获账面与版本。盘点如发生业务变化会拒绝审核；重新实盘后再刷新版本。";}
    private List<InventoryDocumentLine> Lines(){Commit();return Rows.Select(row=>{var b=row.Captured;if(b is null||b.Code!=row.Code)throw new BusinessRuleException("请先核对当前账面，SKU变化后须重新核对。");return new InventoryDocumentLine(b.SkuId,row.Value,row.QuarantineCount,b.Version,b.QuarantineVersion,b.SkuVersion);}).ToList();}
    private async Task<InventoryDocumentResult> Post(string url,object body){if(_api.PendingCount>0)throw new BusinessRuleException("请先核清未确认请求。");var r=await _api.PostCommandAsync<InventoryDocumentResult>(url,body);StatusText.Text=r.Message;return r;}
    public async Task CreateAsync(){if(_document is not null)throw new BusinessRuleException("请先点新建。");var result=await Post("/api/inventory-documents",new{number=NumberBox.Text,kind=((InventoryKindChoice)KindBox.SelectedItem).Kind,lines=Lines(),reason=ReasonBox.Text,evidence=EvidenceBox.Text});await RefreshAsync();await LoadAsync(result.Id);}
    public async Task EditAsync(){var d=_document??throw new BusinessRuleException("请打开草稿。");var r=await Post($"/api/inventory-documents/{d.Id}/edit",new{expectedVersion=d.Version,lines=Lines(),reason=ReasonBox.Text,evidence=EvidenceBox.Text});await RefreshAsync();await LoadAsync(r.Id);}
    public async Task ApproveAsync(){var d=_document??throw new BusinessRuleException("请选择单据。");if(d.CreatedBy==_api.CurrentAccount?.Id)throw new BusinessRuleException("制单人不能审核，请另一账号操作。");Commit();if(EvidenceBox.Text!=d.Evidence||Rows.Count!=d.Lines.Count||Rows.Any(row=>{var l=d.Lines.SingleOrDefault(x=>x.SkuId==row.Captured?.SkuId);return l is null||row.Code!=row.Captured?.Code||row.Value!=(d.Kind==InventoryDocumentKind.Count?l.OnHandBefore+l.OnHandDelta:d.Kind==InventoryDocumentKind.Adjustment||d.Kind==InventoryDocumentKind.Reversal?l.OnHandDelta:-l.QuarantineDelta)||row.QuarantineCount!=(d.Kind==InventoryDocumentKind.Count?l.QuarantineBefore+l.QuarantineDelta:0);}))throw new BusinessRuleException("有未保存的明细或依据修改，请保存草稿或重新打开后再审核。");var r=await Post($"/api/inventory-documents/{d.Id}/approve",new{expectedVersion=d.Version,reason=ReasonBox.Text});await RefreshAsync();await LoadAsync(r.Id);}
    public async Task VoidAsync(){var d=_document??throw new BusinessRuleException("请选择草稿。");var r=await Post($"/api/inventory-documents/{d.Id}/void",new{expectedVersion=d.Version,reason=ReasonBox.Text});await RefreshAsync();await LoadAsync(r.Id);}
    public async Task ReverseAsync(){var d=_document??throw new BusinessRuleException("请选择原审核单。");var r=await Post($"/api/inventory-documents/{d.Id}/reverse",new{expectedVersion=d.Version,number="REV-"+Guid.NewGuid().ToString("N"),reason=ReasonBox.Text,evidence=EvidenceBox.Text});await RefreshAsync();await LoadAsync(r.Id);}
    public async Task LoadAsync(string id){var details=await _api.GetAsync<InventoryDocumentDetails>("/api/inventory-documents/"+id);var d=details.Document;_document=d;NumberBox.Text=d.Number;KindBox.SelectedItem=KindBox.Items.Cast<InventoryKindChoice>().Single(x=>x.Kind==d.Kind);KindBox.IsEnabled=false;NumberBox.IsReadOnly=true;ReasonBox.Text=d.Reason;EvidenceBox.Text=d.Evidence;Rows.Clear();foreach(var l in d.Lines){var b=await _api.GetAsync<InventoryDocumentBalance>("/api/inventory-documents/balance/"+l.SkuId);Rows.Add(new(){Code=b.Code,StoredHandDelta=l.OnHandDelta,StoredQuarantineDelta=l.QuarantineDelta,Value=d.Kind==InventoryDocumentKind.Count?l.OnHandBefore+l.OnHandDelta:d.Kind==InventoryDocumentKind.Adjustment||d.Kind==InventoryDocumentKind.Reversal?l.OnHandDelta:-l.QuarantineDelta,QuarantineCount=d.Kind==InventoryDocumentKind.Count?l.QuarantineBefore+l.QuarantineDelta:0,BookOnHand=l.OnHandBefore,BookQuarantine=l.QuarantineBefore,Reserved=b.Reserved,Frozen=b.Frozen,Captured=b with{Version=l.InventoryVersion,QuarantineVersion=l.QuarantineVersion,SkuVersion=l.SkuVersion}});}MovementsGrid.ItemsSource=details.Movements;HistoryGrid.ItemsSource=details.History;Permissions();}
    private async void Search_Click(object s,RoutedEventArgs e)=>await Run(async()=>{_page=1;await RefreshAsync();});private async void Previous_Click(object s,RoutedEventArgs e)=>await Run(async()=>{if(_page>1)_page--;await RefreshAsync();});private async void Next_Click(object s,RoutedEventArgs e)=>await Run(async()=>{_page++;await RefreshAsync();});
    private async void Open_Click(object s,RoutedEventArgs e)=>await Run(async()=>{if(DocumentsGrid.SelectedItem is InventoryDocument d)await LoadAsync(d.Id);});private void New_Click(object s,RoutedEventArgs e)=>NewDocument();private async void Capture_Click(object s,RoutedEventArgs e)=>await Run(CaptureAsync);private async void Create_Click(object s,RoutedEventArgs e)=>await Run(CreateAsync);private async void Edit_Click(object s,RoutedEventArgs e)=>await Run(EditAsync);private async void Void_Click(object s,RoutedEventArgs e)=>await Run(VoidAsync);private async void Approve_Click(object s,RoutedEventArgs e)=>await Run(ApproveAsync);private async void Reverse_Click(object s,RoutedEventArgs e)=>await Run(ReverseAsync);
    private async void Audit_Click(object s,RoutedEventArgs e)=>await Run(async()=>{var audit=await _api.GetAsync<InventoryDocumentAudit>("/api/inventory-documents/audit");StatusText.Text=audit.Passed?$"已核对{audit.CheckedDocuments}张单据，明细与流水一致。":string.Join("；",audit.Problems);});
}
